using OCRS.Models.Enums; using System.ComponentModel.DataAnnotations; using System.ComponentModel.DataAnnotations.Schema;
namespace OCRS.Models;
public class Course { public int CourseId { get; set; } [Required, StringLength(20)] public string CourseCode { get; set; } = ""; [Required, StringLength(160)] public string CourseName { get; set; } = ""; public int CategoryId { get; set; } public Category Category { get; set; } = null!; [StringLength(3000)] public string? Description { get; set; } [StringLength(2000)] public string? Objectives { get; set; } [Range(1,1000)] public int Duration { get; set; } [Column(TypeName="decimal(18,2)"), Range(0,double.MaxValue)] public decimal TuitionFee { get; set; } [StringLength(300)] public string? ImageUrl { get; set; } public LearningMode LearningMode { get; set; } public CourseStatus Status { get; set; } = CourseStatus.Draft; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public DateTime? UpdatedAt { get; set; } public ICollection<CourseClass> Classes { get; set; } = []; }
